package com.andye.warmod.radar.client.gui;import com.andye.warmod.radar.*;import com.andye.warmod.radar.client.*;import java.util.*;import net.minecraft.client.gui.*;import net.minecraft.network.chat.Component;import net.minecraft.world.phys.Vec3;public final class RadarSidebar{private RadarSidebar(){}public static void render(GuiGraphicsExtractor g,Font f,ClientRadarState state,double now,int left,int top,int width,int height,int scroll){g.fill(left,top,left+width,top+height,0xee10171b);g.enableScissor(left,top,left+width,top+height);int y=top+8-scroll;g.text(f,Component.literal("TRACKS"),left+8,y,0xffffffff);y+=14;for(var t:state.tracks()){boolean selected=t.id().equals(state.selectedTrackId());if(selected)g.fill(left+5,y-2,left+width-5,y+11,0xff34444c);int color=t.snapshot().kind()==RadarTrackKind.INTERCEPTOR?0xff67ddec:0xffd5b06a;g.text(f,Component.literal(t.id().toString().substring(0,8)+"  "+t.snapshot().phase().label()),left+8,y,selected?0xffffffff:color);y+=14;}var t=state.selected();if(t!=null){y+=5;var s=t.snapshot();Vec3 p=t.position(now),v=t.velocity(now),target=t.target();line(g,f,"TRACK",s.trackId().toString().substring(0,8),left,y);y+=20;line(g,f,"TRACK TYPE",s.kind()==RadarTrackKind.INTERCEPTOR?"Interceptor":s.kind().name(),left,y);y+=20;line(g,f,"LAUNCHED BY",s.ownerDisplayName(),left,y);y+=20;if(s.kind()==RadarTrackKind.INTERCEPTOR){var ip=s.interceptorPlan().orElseThrow();line(g,f,"VARIANT",ip.variant()==com.andye.warmod.antiair.AntiAirMissileVariant.MK_I?"Mk I":"Mk II",left,y);y+=20;line(g,f,"TARGET",ip.targetRootTrackId().map(id->id.toString().substring(0,8)).orElse("NONE"),left,y);y+=20;line(g,f,"GUIDANCE","Tier "+ip.guidanceTier(),left,y);y+=20;line(g,f,"MISS ALLOWANCE",String.format(Locale.ROOT,"%.0f blocks",ip.maximumMissDistance()),left,y);y+=20;}else{line(g,f,"PAYLOAD",s.strategicPayloadType().map(Enum::name).orElse("--"),left,y);y+=20;}line(g,f,"STAGE",s.phase().label(),left,y);y+=20;line(g,f,"POSITION",format(p),left,y);y+=20;line(g,f,"SPEED",String.format(Locale.ROOT,"%.1f blocks/s",v.length()*20),left,y);y+=20;line(g,f,"PLANNED POINT",format(target),left,y);y+=20;line(g,f,"DISTANCE",String.format(Locale.ROOT,"%.0f blocks",p.distanceTo(target)),left,y);}g.disableScissor();}private static void line(GuiGraphicsExtractor g,Font f,String l,String v,int x,int y){g.text(f,Component.literal(l),x+8,y,0xff7e99a5);g.text(f,Component.literal(v),x+8,y+9,0xffffffff);}private static String format(Vec3 p){return String.format(Locale.ROOT,"%.0f / %.0f / %.0f",p.x,p.y,p.z);}}